import React from 'react';
import '../styles/Blog.css';

// Datos de ejemplo para las publicaciones del blog
const posts = [
  {
    id: 1,
    title: '5 Claves para la Declaración de Renta de Personas Naturales',
    excerpt: 'La temporada de declaración de renta puede ser un desafío. Te compartimos 5 claves esenciales para que presentes tu declaración sin contratiempos y aproveches las deducciones a tu favor.',
    imageUrl: 'https://res.cloudinary.com/diyd6flkf/image/upload/v1716840931/blog-post-1_tq9z9q.jpg',
    date: '15 de Mayo, 2024'
  },
  {
    id: 2,
    title: '¿Por Qué tu Pyme Necesita un Asesor Contable?',
    excerpt: 'Descubre cómo un asesor contable puede transformar la salud financiera de tu pequeña o mediana empresa, optimizando recursos y garantizando el cumplimiento normativo.',
    imageUrl: 'https://res.cloudinary.com/diyd6flkf/image/upload/v1716840931/blog-post-2_u9v8vx.jpg',
    date: '28 de Abril, 2024'
  },
  {
    id: 3,
    title: 'Facturación Electrónica en Colombia: Lo que Debes Saber en 2024',
    excerpt: 'La facturación electrónica es obligatoria y trae consigo muchos beneficios. Mantente al día con los últimos requisitos y saca el máximo provecho de esta herramienta digital.',
    imageUrl: 'https://res.cloudinary.com/diyd6flkf/image/upload/v1716840931/blog-post-3_b9z8z9.jpg',
    date: '10 de Abril, 2024'
  }
];

const Blog = () => {
  return (
    <div className="blog-container">
      <h1 className="blog-main-title">Nuestro Blog</h1>
      <p className="blog-intro">
        Mantente informado con las últimas noticias, consejos y análisis del mundo contable y financiero.
      </p>
      <div className="blog-posts-grid">
        {posts.map(post => (
          <div key={post.id} className="blog-post-card">
            <img src={post.imageUrl} alt={post.title} className="blog-post-image" />
            <div className="blog-post-content">
              <p className="blog-post-date">{post.date}</p>
              <h2 className="blog-post-title">{post.title}</h2>
              <p className="blog-post-excerpt">{post.excerpt}</p>
              <a href={`/blog/${post.id}`} className="blog-post-readmore">Leer más &rarr;</a>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Blog;
